def standardize_region(df):
    out = df.copy()
    out["region"] = out["region"].str.strip().str.title()
    return out

def clean_orders(raw):
    """Full pipeline: dedupe, standardize, add revenue."""
    return (raw.drop_duplicates(subset="order_id")
               .pipe(standardize_region).pipe(add_revenue))
